<script setup lang="ts">
import { computed,ref } from 'vue'
import { ElDrawer } from 'element-plus'
import { useUiStore } from '../../stores/ui.store'
import { usePhrasesStore } from '../../stores/phrases.store'
const ui=useUiStore(),p=usePhrasesStore(),q=ref('')
const list=computed(()=>p.phrases.filter(x=>(!ui.phraseFavoritesOnly||x.favorite)&&(!q.value||x.text.toLowerCase().includes(q.value.toLowerCase()))).slice(0,250))
function choose(id:string){p.select(id);ui.phrasesOpen=false}
</script><template><ElDrawer v-model="ui.phrasesOpen" :title="ui.phraseFavoritesOnly?'Preferiti':'Raccolta frasi'" size="min(560px, 94vw)"><div class="phrase-filters"><input v-model="q" placeholder="Cerca tra i pensieri…"/><button class="quiet-button" @click="ui.phraseFavoritesOnly=!ui.phraseFavoritesOnly">{{ui.phraseFavoritesOnly?'Tutte':'Solo preferiti'}}</button></div><div class="phrase-list"><article v-for="x in list" :key="x.id" :class="{active:x.id===p.current?.id}"><button class="text serif" @click="choose(x.id)">{{x.text}}</button><button class="heart" :class="{on:x.favorite}" @click="p.toggleFavorite(x)">{{x.favorite?'♥':'♡'}}</button></article><div v-if="!list.length" class="empty">Nessuna frase trovata.</div></div></ElDrawer></template><style scoped>.phrase-filters{display:flex;gap:.55rem;position:sticky;top:0;background:var(--el-bg-color-overlay);padding-bottom:.8rem;z-index:2}.phrase-filters input{flex:1;min-width:0;border:1px solid var(--glass-border);background:rgba(255,255,255,.04);color:inherit;border-radius:14px;padding:.8rem 1rem}.phrase-list{display:grid}.phrase-list article{display:grid;grid-template-columns:1fr 44px;align-items:center;border-bottom:1px solid rgba(255,255,255,.07)}.phrase-list article.active{background:rgba(158,205,182,.07)}.text,.heart{border:0;background:transparent;color:inherit}.text{text-align:left;padding:1rem .2rem;line-height:1.55;cursor:pointer}.heart{font-size:1.35rem;cursor:pointer;color:var(--text-muted)}.heart.on{color:#eab3b3}</style>